'use strict';
(()=>{
 const engine=window.CourtsideSearch,$=s=>document.querySelector(s),escape=s=>engine.highlight(s,''),form=$('#site-search-form'),input=$('#site-search-input'),priority=$('#priority'),hiddenContext=$('#search-context');
 let worker,request=0,result=null,selected='all',limits={},query='',context='courts';
 const allowed=new Set([...Object.keys(engine.contexts),'pages']);
 function readURL(){const params=new URLSearchParams(location.search);query=(params.get('q')||'').slice(0,240);context=allowed.has(params.get('context'))?params.get('context'):'courts';input.value=query;hiddenContext.value=context;priority.value=({desk:'courts',about:'pages',sources:'pages'})[context]||context;}
 function updateURL(push=true){const url=new URL('/search/',location.origin);if(query)url.searchParams.set('q',query);url.searchParams.set('context',context);history[push?'pushState':'replaceState'](null,'',url);}
 function start(){request++;result=null;selected='all';limits={};$('#search-results').innerHTML='';$('#search-categories').innerHTML='';document.title=(query?'Search: '+query:'Search all Courtside Texas')+' | Courtside Texas';if(!engine.tokens(query).length){$('#search-status').textContent='Enter a court, topic, or phrase to search across Courtside Texas.';return;}$('#search-status').textContent='Searching courts, rules, news and agencies…';try{if(!worker){worker=new Worker('/assets/search-engine.d0de3470d21c.js');worker.onmessage=({data})=>{if(data.id!==request)return;if(data.error){error(data.error);return;}result=data;render();};worker.onerror=()=>{worker.terminate();worker=null;error('Search could not start. Check your connection and try again.');};}worker.postMessage({id:request,query,context});}catch{error('Search could not start in this browser. Try an updated browser, or browse the linked directories below.');}}
 function error(message){$('#search-status').textContent=message;$('#search-results').innerHTML='<button class="outline" id="retry-search">Retry search</button> <a href="/courts/">Browse courts</a> · <a href="/rules/">Browse rules</a> · <a href="/news/">Browse news</a>';$('#retry-search').onclick=start;}
 function urlFor(item){const u=new URL(item.url,location.origin);if(item.kind==='local'||item.kind==='practice')u.searchParams.set('q',query);return u.href;}
 function card(item){const external=/^https?:/.test(item.url),highlight=s=>engine.highlight(s,query);return `<article class="search-result"><p class="search-result-meta">${escape(engine.groups[item.kind])}${item.related?' · Matched through a linked rule':''}${item.status?' · '+escape(item.fullText?(['stale','cached-source'].includes(item.status)?'Previously retrieved text':'Indexed rule text'):'Title match'):''}</p><h3><a href="${escape(urlFor(item))}"${external?' target="_blank" rel="noopener"':''}>${highlight(item.title)}${external?' ↗':''}</a></h3><p class="search-result-detail">${highlight(item.detail||'')}</p>${item.snippet?`<p class="search-result-snippet">${highlight(item.snippet)}</p>`:''}${item.sourceUrl?`<a class="search-source" href="${escape(item.sourceUrl)}" target="_blank" rel="noopener">${item.kind==='courts'?'Official court website':'Official document'} ↗</a>`:''}</article>`;}
 function render(){const label=engine.contexts[context]||'Site information first';$('#search-status').textContent=`${result.total.toLocaleString()} ${result.total===1?'match':'matches'} for “${query}”. ${label}.${result.loading?' Searching full rule text…':''}${result.warning?' '+result.warning:''}`;$('#search-results').setAttribute('aria-busy',String(result.loading));$('#search-categories').innerHTML=[{kind:'all',label:'All results',items:{length:result.total}},...Object.entries(engine.groups).map(([kind,label])=>result.groups.find(g=>g.kind===kind)||{kind,label,items:[]})].map(g=>`<button type="button" class="chip ${selected===g.kind?'active':''}" data-category="${g.kind}" aria-pressed="${selected===g.kind}">${escape(g.label)} <span>${g.items.length}</span></button>`).join('');$('#search-results').innerHTML=result.groups.filter(g=>selected==='all'||selected===g.kind).map(g=>{const limit=limits[g.kind]||3;return `<section class="search-group" id="results-${g.kind}"><div class="search-group-title"><h2>${escape(g.label)}</h2><span>${g.items.length} ${g.items.length===1?'match':'matches'}</span></div>${g.items.slice(0,limit).map(card).join('')}${g.items.length>limit?`<button class="outline" data-more-kind="${g.kind}">Show more ${escape(g.label.toLowerCase())} (${g.items.length-limit} remaining)</button>`:''}</section>`;}).join('')||(!result.loading?`<div class="empty"><h2>${selected==='all'?'No matches found.':'No matches in '+escape(engine.groups[selected])+'.'}</h2><p>${selected==='all'?'Try fewer words, a court or county name, or a broader topic.':'Choose All results to see matches from the other sections.'}</p></div>`:'');$('#search-categories').querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=b.dataset.category;render();});document.querySelectorAll('[data-more-kind]').forEach(b=>b.onclick=()=>{const kind=b.dataset.moreKind,y=scrollY;limits[kind]=(limits[kind]||3)+10;render();scrollTo(0,y);});}
 form.addEventListener('submit',e=>{e.preventDefault();query=input.value.trim().slice(0,240);updateURL();start();});priority.addEventListener('change',()=>{context=priority.value;hiddenContext.value=context;updateURL();start();});window.addEventListener('popstate',()=>{readURL();start();});readURL();start();
})();
